create extension if not exists pgcrypto;
create type document_status as enum ('Importado','Na fila','Processando','Revisão necessária','Pronto para envio','Enviando','Enviado','Parcial','Erro','Cancelado');
create table offices (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz default now());
create table profiles (id uuid primary key references auth.users, office_id uuid not null references offices, name text not null, role text default 'operator');
create table clients (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, legal_name text not null, trade_name text, cnpj text not null, owner_name text, email text, whatsapp text, preference text, active boolean default true, notes text, created_at timestamptz default now(), unique(office_id,cnpj));
create table contacts (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, client_id uuid not null references clients on delete cascade, kind text not null, value text not null, is_primary boolean default false);
create table documents (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, client_id uuid references clients, original_name text not null, final_name text, hash text not null, storage_path text not null, extracted_cnpj text, competence text, due_date date, amount numeric(14,2), status document_status default 'Importado', created_at timestamptz default now(), updated_at timestamptz default now(), unique(office_id,hash));
create table processings (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, document_id uuid not null references documents on delete cascade, current_step int default 1, status text default 'Na fila', progress int default 0, error_message text, started_at timestamptz, finished_at timestamptz, updated_at timestamptz default now());
create table processing_steps (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, processing_id uuid not null references processings on delete cascade, step int not null, name text not null, status text not null, message text, created_at timestamptz default now());
create table attempts (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, processing_id uuid not null references processings, attempt int not null, request jsonb, response jsonb, created_at timestamptz default now());
create table deliveries (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, document_id uuid not null references documents, channel text not null, status text not null, sent_at timestamptz, error_message text);
create table alerts (id uuid primary key default gen_random_uuid(), office_id uuid not null references offices, document_id uuid references documents, type text not null, severity text not null, title text not null, resolved_at timestamptz, created_at timestamptz default now());
create table audit_logs (id bigint generated always as identity primary key, office_id uuid not null references offices, actor_id uuid references auth.users, action text not null, entity text not null, entity_id text, metadata jsonb default '{}', created_at timestamptz default now());
alter table offices enable row level security; alter table profiles enable row level security; alter table clients enable row level security; alter table contacts enable row level security; alter table documents enable row level security; alter table processings enable row level security; alter table processing_steps enable row level security; alter table attempts enable row level security; alter table deliveries enable row level security; alter table alerts enable row level security; alter table audit_logs enable row level security;
create function current_office() returns uuid language sql stable security definer set search_path=public as $$ select office_id from profiles where id=auth.uid() $$;
create policy office_isolation on offices for all using(id=current_office());
create policy profile_isolation on profiles for all using(office_id=current_office());
create policy client_isolation on clients for all using(office_id=current_office()) with check(office_id=current_office());
create policy contact_isolation on contacts for all using(office_id=current_office()) with check(office_id=current_office());
create policy document_isolation on documents for all using(office_id=current_office()) with check(office_id=current_office());
create policy processing_isolation on processings for all using(office_id=current_office()) with check(office_id=current_office());
create policy step_isolation on processing_steps for all using(office_id=current_office()) with check(office_id=current_office());
create policy attempt_isolation on attempts for all using(office_id=current_office()) with check(office_id=current_office());
create policy delivery_isolation on deliveries for all using(office_id=current_office()) with check(office_id=current_office());
create policy alert_isolation on alerts for all using(office_id=current_office()) with check(office_id=current_office());
create policy audit_isolation on audit_logs for select using(office_id=current_office());
insert into storage.buckets(id,name,public) values('das-documents','das-documents',false) on conflict do nothing;
